</div></div></div>

<header class="stick">
<div class="hd">
<a class="logo" href="index.html">
<svg class="seal" viewBox="0 0 40 40" aria-hidden="true"><rect x="1" y="1" width="38" height="38" fill="#A63E2A"/><rect x="1" y="1" width="38" height="38" fill="none" stroke="#7E2E1E" stroke-width="2"/><text x="20" y="17" text-anchor="middle" font-size="14" fill="#F4EFE5" font-family="Songti SC,SimSun,serif">叙</text><text x="20" y="33" text-anchor="middle" font-size="14" fill="#F4EFE5" font-family="Songti SC,SimSun,serif">白</text></svg>
